from lib import *
S = SS('j269')
steps = [
    step("API(JDK 21):Signature.getInstance(\"RSASSA-PSS\") 必须先 setParameter(PSSParameterSpec),否则 initSign / sign 抛 SignatureException: Parameters required for RSASSA-PSS signatures;“SHA256withRSA/PSS”“SHA256withRSAandMGF1”“SHA1withRSA/PSS”在 SunRsaSign 里都不存在(NoSuchAlgorithmException)。设置 PSSParameterSpec(\"SHA-256\", \"MGF1\", MGF1ParameterSpec.SHA256, 32, 1) 后 getParameters() 是 RSASSA-PSS SHA-256/32;RSA 2048 的签名长 256 字节(等于模长)。", t=tl(S(1)), done=lidx(S(1), 'RSASSA-PSS 不 setParameter 直接', 'SHA256withRSA/PSS'), mark=lidx(S(1), 'SHA256withRSAandMGF1', 'getParameters()', 'RSA 2048 + SHA-256 + 盐 32'), kv=KV([['不 setParameter', 'SignatureException: Parameters required'], ['SHA256withRSA/PSS 等别名', '不存在'], ['签名长度', '256 字节(= 模长)']], ['不 setParameter'])),
    step("盐:盐长度 0 时同一条消息签 20 次只有 1 个不同的签名(确定性);盐 20 或 32 时 20 次得到 20 个不同的签名。盐的最大长度 = emLen - hLen - 2:RSA 2048 的 emBits = 2047、emLen = 256,所以 SHA-256 最大 222、SHA-512 最大 190、SHA-1 最大 234:盐 222 / 190 / 234 签名成功;盐 223 / 191 / 235 抛 InvalidKeyException: Key is too short, need min 257 bytes(这个错误信息把“盐太长”说成了“密钥太短”)。", t=tl(S(2)), done=lidx(S(2), '盐长度 0', '盐长度 20', '盐长度 32'), mark=lidx(S(2), '盐 222', '盐 223', 'SHA-512 + 盐 190', 'SHA-1 + 盐 235', '上限的计算'), b=bars([['盐 0:不同签名数', 1, '1'], ['盐 20:不同签名数', 20, '20'], ['盐 32:不同签名数', 20, '20']], 20, done=[0, 1, 2]), kv=KV([['盐 0', '确定性(20 次 1 个签名)'], ['SHA-256 最大盐', '222(223 抛 InvalidKeyException)']], ['SHA-256 最大盐'])),
    step("验证时参数不一致:相同参数验证 true;验证时盐长度写 20(签名用 32)false;摘要写 SHA-384 false;MGF1 用 SHA-1 false;用 PKCS#1 v1.5(SHA256withRSA)验证 PSS 签名 false,反过来 PKCS#1 v1.5 的签名用 PSS 验证也是 false;签名翻转 1 位、消息改一个字节都是 false。盐 0 签出的签名用盐 32 验证 false,用盐 0 验证 true。PSS 的验证者必须知道签名者用的参数,Java 不会自动识别盐长度。", t=tl(S(3)), done=lidx(S(3), '同样的参数验证', '验证时盐长度写 20', '验证时摘要写 SHA-384'), mark=lidx(S(3), 'MGF1 用 SHA-1', 'PKCS#1 v1.5(SHA256withRSA)', '翻转 1 位', '盐 0 签名'), kv=KV([['参数一致', 'true'], ['盐长度 / 摘要 / MGF1 / 填充方式不一致', '全部 false'], ['盐 0 的签名用盐 32 验证', 'false']], ['盐 0 的签名用盐 32 验证'])),
    step("RSASSA-PSS 类型的密钥(KeyPairGenerator.getInstance(\"RSASSA-PSS\") 带 PSSParameterSpec):公钥编码 346 字节(普通 RSA 公钥 294 字节,多了参数),参数 SHA-256/盐 32。用一致的参数签名并验证 true;摘要写 SHA-512 或盐 16 抛 InvalidKeyException: Key contains incompatible PSS parameter values;盐 40 成功(密钥限定的是最小盐长度);PSS 密钥不 setParameter 仍然抛 SignatureException;把 PSS 密钥用于 SHA256withRSA 抛 InvalidKeyException: Invalid key for RSA signatures;普通 RSA 私钥配 PSS 参数成功。", t=tl(S(4)), done=lidx(S(4), 'RSASSA-PSS 类型的密钥', '用与密钥参数一致'), mark=lidx(S(4), '摘要 SHA-512', '盐 16', '盐 40', 'PSS 密钥不 setParameter', 'SHA256withRSA', '普通 RSA 私钥配 PSS 参数'), kv=KV([['PSS 类型的密钥', '限定摘要与最小盐长度'], ['不一致的参数', 'InvalidKeyException'], ['普通 RSA 私钥', '可以配任意 PSS 参数']], ['PSS 类型的密钥'])),
    step("与 OpenSSL(4.0.3)互通:openssl pkeyutl -verify -rawin -digest sha256 -pkeyopt rsa_padding_mode:pss,验证 Java 盐 32 的签名(指定盐 32)成功、Java 盐 0 的签名(指定盐 0)成功、对盐 32 的签名指定盐 0 失败(Signature Verification Failure)、rsa_pss_saltlen:auto 成功。OpenSSL 签名后 Java 验证:盐 32 与默认(不指定)的签名用盐 32 验证 true(OpenSSL 默认盐等于摘要长度 32);rsa_pss_saltlen:max 的签名用盐 32 验证 false、用盐 222 验证 true。验证者必须知道对方的盐长度,否则只能让 OpenSSL 用 auto 去自动识别。", t=tl(S(5)), done=lidx(S(5), 'openssl 验证 Java 盐 32 的签名(指定盐 32)', 'Java 盐 0 的签名(指定盐 0)'), mark=lidx(S(5), '指定盐 0):Signature Verification Failure', 'rsa_pss_saltlen:auto', 'ossl_default.sig', 'ossl_max.sig'), kv=KV([['openssl 验证 Java', '盐一致、auto 成功;盐不一致失败'], ['Java 验证 openssl', '默认盐 = 摘要长度 32;max 盐 = 222']], ['openssl 验证 Java'])),
    step("性能(JDK 21,单线程,5 轮中位数):RSA 2048:PKCS#1 v1.5 签名 872 µs、验证 37.5 µs;PSS(SHA-256,盐 32)签名 872 µs、验证 36.3 µs;RSA 3072:PKCS#1 v1.5 签名 2539 µs、验证 68.4 µs;PSS 签名 2544 µs、验证 68.4 µs。PSS 与 PKCS#1 v1.5 的成本没有差别(时间都花在大数模幂上),选 PSS 不需要付性能代价。", t=tl(S(6)), done=lidx(S(6), 'RSA 2048 PKCS#1 v1.5', 'RSA 2048 PSS'), mark=lidx(S(6), 'RSA 3072 PKCS#1 v1.5', 'RSA 3072 PSS'), b=bars([['2048 PKCS#1 v1.5 签名', 872, '872 µs'], ['2048 PSS 签名', 872, '872 µs'], ['3072 PKCS#1 v1.5 签名', 2539, '2539 µs'], ['3072 PSS 签名', 2544, '2544 µs']], 2544, done=[0, 1, 2, 3]), kv=KV([['RSA 2048', 'v1.5 与 PSS 的签名都是 872 µs'], ['RSA 3072', 'v1.5 2539 µs / PSS 2544 µs']], ['RSA 2048'])),
]
A = mkartj('j269', 269, 'Java,密码学,RSASSA-PSS,RSA,签名,盐,OpenSSL,真实验证,动画演示',
    '在 JDK 21 上实测 RSASSA-PSS:必须 setParameter;盐 0 时签名确定、盐 20/32 时每次不同;RSA 2048 的最大盐是 222(SHA-256),超出时抛“Key is too short”;验证者必须知道盐长度;RSASSA-PSS 类型的密钥限定摘要与最小盐;与 OpenSSL 互通;PSS 与 PKCS#1 v1.5 的签名耗时相同(872 µs)。',
    'RSASSA-PSS 是 RSA 签名的推荐填充方式,但 Java 里它的参数、盐长度与密钥类型处处是坑。这篇在 JDK 21 上逐项量出:API 的要求、盐的作用与上限、验证时参数不一致的后果、PSS 类型密钥的限制、与 OpenSSL 的互通,以及性能。',
    [('222', 'RSA 2048 + SHA-256 时 PSS 的最大盐长度(223 抛 InvalidKeyException: Key is too short)'), ('1 vs 20', '盐 0 与盐 32 时,同一消息签 20 次的不同签名个数'), ('872 µs', 'RSA 2048 的 PKCS#1 v1.5 与 PSS 签名耗时(完全相同)')],
    [('API 与必须的参数', None), ('盐', None), ('验证参数不一致', None), ('PSS 类型的密钥', None), ('OpenSSL 互通', None), ('性能', None)],
    steps, [ENV_J + '。JDK 21.0.12(SunRsaSign);OpenSSL 4.0.3(pkeyutl 的摘要要用 -digest,不能用 -pkeyopt digest:);性能是自写的 nanoTime 循环、单线程、5 轮中位数', '没有验证:证书里的 RSASSA-PSS 签名算法标识(X.509 / CMS)、JDK 17 / 27 的差异、更大的密钥(4096)、TLS 1.3 里 rsa_pss_rsae / rsa_pss_pss 的使用、其它提供者(BouncyCastle)'], 'RSASSA-PSS')
